#pragma once
#include "core/Document.h"
#include <string>

namespace kst {

// Native .kst format. A text recipe: parameters, sketches, features and overrides. Geometry is
// regenerated by recompute on load, so files stay small and always match the current kernel.
// Both functions never throw (load returns false with a message).

struct LoadResult {
    bool ok = false;
    std::string error;
    int line = 0;         // 1 based line that failed
    Document doc;
};

bool saveDocument(const Document& doc, const std::string& path);   // atomic: never leaves a half file
// Split form for background saves: serialize on the main thread (fast), write anywhere.
bool serializeDocument(const Document& doc, std::string& out);
bool writeFileAtomic(const std::string& path, const std::string& data);
LoadResult loadDocument(const std::string& path);

} // namespace kst
